    /**
     * Tests creating a new Invoice.
     *
     * @return    Invoice
     */
    public Invoice testCreate() throws Throwable {
    Invoice entity = null;

    LOGGER.info( "InvoiceTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a Invoice");

    StringBuilder msg = new StringBuilder( "-- Failed to create a Invoice" );

    try {
        entity = service.createInvoice( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getInvoiceId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a Invoice with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

    /**
     * Tests reading a Invoice.
     *
     * @return    Invoice
     */
    public Invoice testRead() throws Throwable {
    LOGGER.info( "InvoiceTest:testRead()" );
    LOGGER.info( "-- Reading a previously created Invoice" );

    Invoice entity = null;
    StringBuilder msg = new StringBuilder( "-- Failed to read Invoice with primary key" );
    msg.append( theId );

    try {
        entity = service.getInvoice( new InvoiceFetchOneSummary(theId) );

        assertNotNull( entity,msg.toString() );

        // for use later
        theId = entity.getInvoiceId();

        LOGGER.info( "-- Successfully found Invoice " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests updating a Invoice.
     *
     * @return    Invoice
     */
    public Invoice testUpdate() throws Throwable {
    LOGGER.info( "InvoiceTest:testUpdate()" );
    LOGGER.info( "-- Attempting to update a Invoice." );

    StringBuilder msg = new StringBuilder( "Failed to update a Invoice : " );
    Invoice entity = null;

    try {
        UpdateInvoiceCommand updateCommand = this.generateUpdateCommand();

        // apply the current id as to update the fields of the current entity
        updateCommand.setInvoiceId( theId );

        assertNotNull( updateCommand, msg.toString() );

        LOGGER.info( "-- Now updating the created Invoice." );

        entity = service.updateInvoice( updateCommand );

        assertNotNull( entity, msg.toString()  );

        LOGGER.info( "-- Successfully saved Invoice - " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : primarykey-" + theId + " : entity-" +  entity + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests deleting a Invoice.
     */
    public void testDelete() throws Throwable {
    LOGGER.info( "InvoiceTest:testDelete()" );
    LOGGER.info( "-- Deleting a previously created Invoice." );

    try {
        DeleteInvoiceCommand deleteCommand = new DeleteInvoiceCommand( theId );

        service.delete( deleteCommand );

        LOGGER.info( "-- Successfully deleted Invoice with primary key " + theId );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( "-- Failed to delete Invoice with primary key " + theId );

        throw e;
    }
}

    /**
     * Tests getting all Invoices.
     *
     * @return    Collection
     */
    public List<Invoice> testGetAll() throws Throwable {
    LOGGER.info( "InvoiceTest:testGetAll() - Retrieving Collection of Invoices:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Invoice : " );
    List<Invoice> collection  = null;

    try {
        // call the static get method on the InvoiceService
        collection = service.getAllInvoice();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Invoice currEntity  = null;
            Iterator<Invoice> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getInvoiceId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

